import pyomo.environ as pyo

DATA = {
    "cities": [1, 2, 3, 4, 5],
    "n": 5,
    "cost": {
        (1, 2): 35, (1, 3): 90, (1, 4): 23, (1, 5): 62,
        (2, 1): 35, (2, 3): 53, (2, 4): 58, (2, 5): 46,
        (3, 1): 90, (3, 2): 53, (3, 4): 28, (3, 5): 91,
        (4, 1): 23, (4, 2): 58, (4, 3): 28, (4, 5): 77,
        (5, 1): 62, (5, 2): 46, (5, 3): 91, (5, 4): 77,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    cities = d["cities"]
    n = d["n"]
    cost = d["cost"]

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=cities, ordered=True)
    model.A = pyo.Set(
        initialize=[(i, j) for i in cities for j in cities if i != j],
        dimen=2,
    )

    model.x = pyo.Var(model.A, within=pyo.Binary)
    model.u = pyo.Var(model.N, within=pyo.NonNegativeReals,
                      bounds=(1, n))

    def obj_rule(m):
        return sum(cost[(i, j)] * m.x[i, j] for (i, j) in m.A)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def out_rule(m, i):
        return sum(m.x[i, j] for j in m.N if (i, j) in m.A) == 1

    model.out_degree = pyo.Constraint(model.N, rule=out_rule)

    def in_rule(m, j):
        return sum(m.x[i, j] for i in m.N if (i, j) in m.A) == 1

    model.in_degree = pyo.Constraint(model.N, rule=in_rule)

    def anchor_rule(m):
        return m.u[1] == 1

    model.anchor = pyo.Constraint(rule=anchor_rule)

    def mtz_rule(m, i, j):
        if i == 1 or j == 1:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - n * (1 - m.x[i, j])

    model.subtour = pyo.Constraint(model.A, rule=mtz_rule)

    return model
